import streamlit as st
import pandas as pd
import plotly.express as px

st.set_page_config(page_title="HBCU Retention Early-Warning Prototype",
                   page_icon="🎓", layout="wide")

@st.cache_data
def load_data():
    df = pd.read_csv("hbcu_reviewed_output.csv")
    return df

df = load_data()

# ---------- Header ----------
st.title("🎓 HBCU Student Retention Early-Warning Prototype")
st.caption(
    "Proof of concept using synthetic data. Risk levels and intervention "
    "suggestions are generated by a rule-based stand-in for Nemotron. "
    "When real model access arrives, only the text in these columns changes."
)

# ---------- Top metrics ----------
col1, col2, col3, col4, col5 = st.columns(5)
col1.metric("Total students", len(df))
col2.metric("High risk", int((df["risk_level"] == "High").sum()))
col3.metric("Medium risk", int((df["risk_level"] == "Medium").sum()))
col4.metric("Low risk", int((df["risk_level"] == "Low").sum()))
col5.metric("Actual dropout rate", f"{df['has_dropped_out'].mean():.1%}")

st.divider()

# ---------- Charts ----------
left, right = st.columns(2)

with left:
    st.subheader("Risk distribution")
    risk_counts = df["risk_level"].value_counts().reindex(["High", "Medium", "Low"]).fillna(0)
    fig = px.bar(
        x=risk_counts.index, y=risk_counts.values,
        labels={"x": "Risk level", "y": "Students"},
        color=risk_counts.index,
        color_discrete_map={"High": "#d62728", "Medium": "#ff7f0e", "Low": "#2ca02c"},
    )
    fig.update_layout(showlegend=False, height=350)
    st.plotly_chart(fig, use_container_width=True)

with right:
    st.subheader("Dropout rate by risk level")
    dropout_by_risk = df.groupby("risk_level")["has_dropped_out"].mean().reindex(["High", "Medium", "Low"])
    fig2 = px.bar(
        x=dropout_by_risk.index, y=dropout_by_risk.values,
        labels={"x": "Risk level", "y": "Dropout rate"},
        color=dropout_by_risk.index,
        color_discrete_map={"High": "#d62728", "Medium": "#ff7f0e", "Low": "#2ca02c"},
    )
    fig2.update_layout(showlegend=False, height=350, yaxis_tickformat=".0%")
    st.plotly_chart(fig2, use_container_width=True)

st.divider()

# ---------- First-gen vs risk ----------
st.subheader("First-generation share by risk level")
fg_by_risk = df.groupby("risk_level")["first_generation"].apply(lambda s: (s == "Yes").mean()).reindex(["High", "Medium", "Low"])
fig3 = px.bar(
    x=fg_by_risk.index, y=fg_by_risk.values,
    labels={"x": "Risk level", "y": "First-generation share"},
    color=fg_by_risk.index,
    color_discrete_map={"High": "#d62728", "Medium": "#ff7f0e", "Low": "#2ca02c"},
)
fig3.update_layout(showlegend=False, height=350, yaxis_tickformat=".0%")
st.plotly_chart(fig3, use_container_width=True)

st.divider()

# ---------- Filterable student table ----------
st.subheader("Student review list")

fcol1, fcol2, fcol3 = st.columns(3)
risk_filter = fcol1.multiselect("Risk level", ["High", "Medium", "Low"], default=["High"])
housing_filter = fcol2.multiselect("On-campus housing", ["Yes", "No"], default=["Yes", "No"])
fg_filter = fcol3.multiselect("First-generation", ["Yes", "No"], default=["Yes", "No"])

filtered = df[
    df["risk_level"].isin(risk_filter)
    & df["on_campus_housing"].isin(housing_filter)
    & df["first_generation"].isin(fg_filter)
]

st.write(f"Showing **{len(filtered)}** of {len(df)} students")

display_cols = [
    "student_id", "first_generation", "on_campus_housing", "pell_eligible",
    "final_gpa", "final_engagement", "risk_level",
    "risk_reasoning", "intervention_suggestion",
]
st.dataframe(
    filtered[display_cols].sort_values("risk_level"),
    use_container_width=True,
    hide_index=True,
)

st.divider()

# ---------- Single student spotlight ----------
st.subheader("Student spotlight")
if len(filtered) > 0:
    selected_id = st.selectbox("Pick a student", filtered["student_id"].tolist())
    student = df[df["student_id"] == selected_id].iloc[0]

    scol1, scol2 = st.columns([1, 2])
    with scol1:
        st.markdown(f"**Student ID:** {student['student_id']}")
        st.markdown(f"**Risk level:** {student['risk_level']}")
        st.markdown(f"**First-generation:** {student['first_generation']}")
        st.markdown(f"**On-campus housing:** {student['on_campus_housing']}")
        st.markdown(f"**Pell eligible:** {student['pell_eligible']}")
        st.markdown(f"**Final GPA:** {student['final_gpa']}")
        st.markdown(f"**Final engagement:** {student['final_engagement']}")
        st.markdown(f"**Dropped out:** {student['has_dropped_out']}")
    with scol2:
        st.markdown("**Risk reasoning**")
        st.info(student["risk_reasoning"])
        st.markdown("**Suggested intervention**")
        st.success(student["intervention_suggestion"])

st.divider()
st.caption(
    "Prototype note: this dashboard reads synthetic data only. No real student "
    "records are used. In a pilot, Nemotron would run on institution-controlled "
    "infrastructure, and advisors would make all final decisions."
)
